<?php
/* Merge repository seed sources without deleting later admin uploads. */
if($argc<3){fwrite(STDERR,"Usage: php install-knowledge-bundle.php seed.json target.json\n");exit(2);}
$seed=json_decode(@file_get_contents($argv[1]),true);$current=is_file($argv[2])?json_decode(@file_get_contents($argv[2]),true):array();if(!is_array($seed)){fwrite(STDERR,"Invalid seed bundle\n");exit(2);}if(!is_array($current))$current=array();$uploads=array();foreach(isset($current['sources'])?$current['sources']:array()as$source)if(isset($source['origin'])&&$source['origin']==='upload')$uploads[]=$source;$seedSources=isset($seed['sources'])?$seed['sources']:array();$seed['sources']=array_merge($uploads,$seedSources);$chunks=isset($seed['chunks'])?$seed['chunks']:array();foreach($uploads as$source)if(!empty($source['active'])){$text=(string)$source['text'];for($offset=0,$i=0;$offset<strlen($text);$offset+=920,$i++){$part=trim(substr($text,$offset,1100));if(strlen($part)<80)continue;$chunks[]=array('id'=>sha1($source['id'].'#'.$i.'#'.$part),'source_id'=>$source['id'],'url'=>'https://mtpc.edu.vn/tuyen-sinh','title'=>$source['title'],'text'=>$part,'source_type'=>$source['type'],'source_year'=>$source['year'],'updated_at'=>$source['updated_at'],'origin'=>'upload');}}$seed['chunks']=$chunks;$seed['source_count']=count($seed['sources']);$seed['active_source_count']=0;foreach($seed['sources']as$source)if(!empty($source['active']))$seed['active_source_count']++;$seed['chunk_count']=count($chunks);$seed['built_at']=gmdate('c');$dir=dirname($argv[2]);if(!is_dir($dir)&&!mkdir($dir,0750,true)){fwrite(STDERR,"Cannot create target directory\n");exit(2);}$json=json_encode($seed,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT);if(file_put_contents($argv[2].'.tmp',$json,LOCK_EX)===false||!rename($argv[2].'.tmp',$argv[2])){fwrite(STDERR,"Cannot write target bundle\n");exit(2);}echo "Knowledge bundle installed: ".$seed['source_count']." sources, ".$seed['chunk_count']." chunks\n";
